#include <stdio.h>
#include <math.h>
typedef struct{float x,y,z;}V;
static V norm(V v){float l=sqrtf(v.x*v.x+v.y*v.y+v.z*v.z);V r={v.x/l,v.y/l,v.z/l};return r;}
static V add(V a,V b){V r={a.x+b.x,a.y+b.y,a.z+b.z};return r;}
static V sub(V a,V b){V r={a.x-b.x,a.y-b.y,a.z-b.z};return r;}
static V mul(V a,float s){V r={a.x*s,a.y*s,a.z*s};return r;}
static float dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
typedef struct{float t;V p,n;int hit;}H;
static H sph(V o,V d,V c,float r){
  V oc=sub(o,c);
  float a=dot(d,d);
  float b=2.0f*dot(oc,d);
  float cc=dot(oc,oc)-r*r;
  float disc=b*b-a*cc;
  H h;h.hit=0;h.t=0;
  if(disc<0)return h;
  double sq=sqrt((double)disc);
  float t=(float)(((double)(-b)-sq)/(double)(a+a));
  if(t<0.001f){
    t=(float)(((double)(-b)+sq)/(double)(a+a));
    if(t<0.001f)return h;
  }
  h.hit=1;h.t=t;
  h.p=add(o,mul(d,t));
  V nn=sub(h.p,c);
  float l=sqrtf(nn.x*nn.x+nn.y*nn.y+nn.z*nn.z);
  h.n.x=nn.x/l;h.n.y=nn.y/l;h.n.z=nn.z/l;
  return h;
}
static V sky(V d){
  float t=(d.y+1.0f)*0.5f, it=1.0f-t;
  V r={0.5f*t+it,0.7f*t+it,t+it};
  return r;
}
int main(void){
  fprintf(stderr,"Creating high-resolution image: %dx%d\n",800,600);
  fwrite("This will be downsampled with ffmpeg after rendering\n",1,53,stderr);
  V light=norm((V){1.0f,1.0f,-1.0f});
  V center={0.0f,-0.5f,-5.0f};
  float rad=1.0f;
  float *row=malloc(800*3*sizeof(float));
  fwrite("Rendering high-resolution image...\n",1,35,stderr);
  FILE*f=fopen("image.ppm","w");
  fprintf(f,"P3\n%d %d\n255\n",800,600);
  for(int y=0;y<600;y++){
    fprintf(stderr,"\rProgress: %.1f%%",(float)y*100.0f/600.0f);
    for(int x=0;x<800;x++){
      float u=(float)x/799.0f;
      float vv=1.0f-(float)y/599.0f;
      V d=norm((V){u*2.6666667f-1.3333334f,2.0f*vv-1.0f,-1.0f});
      V col;
      H hs=sph((V){0,0,0},d,center,rad);
      float tp=-1.0f; int ph=0;
      if(fabsf(d.y)>=0.0001f){tp=-1.5f/d.y;if(tp>=0.001f)ph=1;}
      int useSphere=0,usePlane=0;
      if(hs.hit&&ph){if(tp>hs.t)useSphere=1;else usePlane=1;}
      else if(hs.hit)useSphere=1;
      else if(ph)usePlane=1;
      if(useSphere){
        V p=hs.p,n=hs.n;
        V so=add(p,mul(n,0.001f));
        H sh=sph(so,norm(light),center,rad);
        float df;
        if(sh.hit)df=0.2f;
        else df=0.2f+0.8f*(float)fmax((double)dot(n,light),0.0);
        col.x=df;col.y=0.2f*df;col.z=0.2f*df;
      } else if(usePlane){
        V p=mul(d,tp);
        V so={p.x,p.y+0.001f,p.z};
        H sh=sph(so,norm(light),center,rad);
        float df;
        if(sh.hit)df=0.2f;
        else df=0.2f+0.8f*(float)fmax((double)light.y,0.0);
        float c=(int)(floorf(p.x))+ (int)(floorf(p.z));
        float base=((int)c&1)?0.4f:0.9f;
        float v=base*df;
        col.x=v;col.y=v;col.z=v;
      } else col=sky(d);
      row[x*3]=col.x;row[x*3+1]=col.y;row[x*3+2]=col.z;
    }
    for(int x=0;x<800;x++){
      float a=fmin(fmax(row[x*3],0.0),1.0);
      float b=fmin(fmax(row[x*3+1],0.0),1.0);
      float c=fmin(fmax(row[x*3+2],0.0),1.0);
      fprintf(f,"%d %d %d\n",(int)(a*255.99f),(int)(b*255.99f),(int)(c*255.99f));
    }
  }
  fclose(f);
  fprintf(stderr,"Wrote image to %s\n","image.ppm");
  fwrite("Done.\n",1,6,stderr);
  return 0;
}
EOF
